package com.singtel.redemptionservice;import java.math.*;import com.singtel.platformcommon.DomainError;
public final class Money{public static BigDecimal discount(String type,BigDecimal value,BigDecimal spend,String currency){if(!"SGD".equals(currency)||spend.signum()<0)throw DomainError.invalid("INVALID_CURRENCY","Only SGD and non-negative spend are supported");return switch(type){case "PERCENTAGE"->spend.multiply(value).divide(new BigDecimal("100"),8,RoundingMode.HALF_UP).min(spend).setScale(2,RoundingMode.HALF_UP);case "FIXED"->value.min(spend).setScale(2,RoundingMode.HALF_UP);case "BENEFIT"->new BigDecimal("0.00");default->throw DomainError.invalid("INVALID_DISCOUNT","Unsupported discount type");};}}